const llm = $json; let p = {};
try { const c = llm.choices && llm.choices[0] && llm.choices[0].message && llm.choices[0].message.content; if (c) p = JSON.parse(c); } catch(e){ p = { _err: String(e) }; }
const project = $('Lookup projet').first().json;
const now = new Date().toISOString();
return [{ json: {
  id: 'site_' + Date.now(),
  ts: now,
  project_id: project.id,
  client_name: project.client_name || '',
  niche: project.niche || '',
  city: project.city || '',
  blueprint_json: JSON.stringify(p.site_blueprint || {}),
  review_notes: JSON.stringify(p.review_notes || []),
  status: p._err ? 'error' : 'draft_pending_review',
  validated_by: '',
  validated_at: ''
}}];
